# Placeholder script for cybersecurity lab# Demonstrates the download-and-execute flow without any payload$logPath = "$env:USERPROFILE\Desktop\lab_log.txt""Script executed at $(Get-Date)" | Out-File -FilePath $logPath -Append# Demonstrate the same command patterns the tutorial uses, but harmless:# - Set execution policy# - Add a folder# - Write a file# - Clean upSet-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force$labDir = "$env:USERPROFILE\Desktop\lab_folder"New-Item -ItemType Directory -Path $labDir -Force | Out-Null"Lab placeholder ran successfully." | Out-File -FilePath "$labDir\result.txt"# Note: no AV exclusion, no downloads, no reverse shell.